//! The x86 decoding tables' constants, generated by tools/x86-rust.mjs from
//! src/core/x86/tables.ts (itself generated by tools/x86-index.mjs from the X86
//! target description of LLVM 21.1.8). Do not edit: run the tools again.
//!
//! The tables themselves are tables.bin, the blob of tables.ts still deflated;
//! decode.rs inflates it once, on first use.
//!
//! LLVM is under the Apache License 2.0 with LLVM Exceptions. What is kept here
//! are facts about the encoding: which instruction each opcode selects in each
//! context, where its operands are encoded, and the Intel syntax of each.

pub const LLVM_VERSION: &str = "21.1.8";
pub const CONTEXT_COUNT: usize = 219;
pub const PRINT_METHODS: [&str; 30] = ["printOperand", "printdwordmem", "printqwordmem", "printwordmem", "printbytemem", "printxmmwordmem", "printSTiRegOperand", "printMemReference", "printU8Imm", "printPCRelImm", "printCondCode", "printCondFlags", "printSrcIdx8", "printDstIdx8", "printSrcIdx32", "printDstIdx32", "printSrcIdx64", "printDstIdx64", "printSrcIdx16", "printDstIdx16", "printzmmwordmem", "printtbytemem", "printMemOffs16", "printMemOffs32", "printMemOffs64", "printMemOffs8", "printTILEPair", "printymmwordmem", "printRoundingControl", "printVKPair"];
pub const SUFFIXES: [&str; 16] = ["", "pd", "ps", "sd", "ss", "ph", "sh", "bf16", "b", "w", "d", "q", "ub", "uw", "ud", "uq"];
/// (instruction, [(operand, value)…], text): printed as the text when its immediates have those values.
pub type Alias = (u32, &'static [(usize, i64)], &'static str);
pub const ALIASES: [Alias; 3] = [(2, &[(0, 10)], "aad"), (7, &[(0, 10)], "aam"), (20675, &[], "xstorerng")];
/// The parts of the blob, in order.
pub const PARTS: [&str; 12] = ["contexts", "ctxBlock", "blockTypes", "blockOffsets", "modrm", "opset", "template", "info", "sem", "sets", "pairs", "templates"];
/// What rep and repne print as before a locked instruction or an xchg (they are not in the tables).
pub const XRELEASE: &str = "xrelease";
pub const XACQUIRE: &str = "xacquire";
/// Instructions the decoder treats specially, by LLVM's name.
pub mod special {
    pub const REP_PREFIX: u32 = 2844;
    pub const REPNE_PREFIX: u32 = 2843;
    pub const LOCK_PREFIX: u32 = 1499;
    pub const DATA16_PREFIX: u32 = 935;
}
/// The tables, deflated (raw deflate, as tables.ts keeps them in base64).
pub static BLOB: &[u8] = include_bytes!("tables.bin");
